vec4 alphaBlend(vec4 bottom, vec4 top) {
    // Formula for opaque bottom and alpha-premultiplied top
    return vec4(bottom.rgb * (1.0 - top.a) + top.rgb, 1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec4 color = texture(iChannel0, fragCoord / iResolution.xy); // Color is alpha-premultiplied
    fragColor = alphaBlend(vec4(1.0), color);
}

#define MAX_RANDOM_OFFSET 3.0       // Higher value for faster diffusion
#define RANDOM_RATIO 2              // Higher value for more regular expansion
#define HARD_EDGE_POW_FACTOR 0.8    // Higher value for softer edges
#define HARD_EDGE_POW_THRESHOLD 0.1 // Higher value for harder edges

// Generate a random offset for diffusion using a noise texture
vec2 randomOffset(vec2 coord) {
    return (texture(iChannel2, coord / iChannelResolution[2].rg).rg * 2.0 - 1.0) * MAX_RANDOM_OFFSET;
}

// Perform alpha blending with a premultiplied bottom layer and normal top layer
// Return alpha-premultiplied color
vec4 alphaBlend(vec4 bottom, vec4 top) {
    return vec4(mix(bottom.rgb, top.rgb, top.a), mix(bottom.a, 1.0, top.a));
}

// Create a circle with a smooth alpha transition
vec4 circle(vec2 coord, vec2 center, float radius, vec3 color) {
    radius *= iResolution.x; // Scale radius by screen resolution
    float alpha = smoothstep(radius + 5.0, radius - 5.0, length(coord - center * iResolution.xy));
    return vec4(color, alpha);
}

// Main function to handle frame rendering
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    if (iFrame == 0) {
        // Initialize with color circles on transparent background on the first frame
        fragColor = vec4(0.0);
        fragColor = alphaBlend(fragColor, circle(fragCoord, vec2(0.35, 0.5), 0.1, vec3(0.9, 0.1, 0.1)));
        fragColor = alphaBlend(fragColor, circle(fragCoord, vec2(0.65, 0.5), 0.1, vec3(0.1, 0.1, 0.9)));
    } else {
        // Offsets for neighbors (left, right, top, bottom)
        vec2 offsets[4] = vec2[4](
            vec2(-1.0, 0.0), vec2(1.0, 0.0),
            vec2(0.0, -1.0), vec2(0.0, 1.0)
        );

        vec4 accumulatedColor = vec4(0.0);

        // Loop over neighbors and sum them
        for (int i = 0; i < 4; i++) {
            vec2 neighborCoord = fragCoord + offsets[i];

            if (iFrame % RANDOM_RATIO == 0) {
                neighborCoord = fragCoord + offsets[i] * randomOffset(neighborCoord);
            }

            vec4 premultipliedColor = texture(iChannel1, neighborCoord / iResolution.xy);
            accumulatedColor += premultipliedColor;
        }

        // Average and process the accumulated color
        if (accumulatedColor.a > 0.0) {
            vec4 averageColor = accumulatedColor / 4.0;

            // Adjust alpha for harder or softer edges
            if (averageColor.a > HARD_EDGE_POW_THRESHOLD) {
                averageColor.rgb /= averageColor.a; // Unpremultiply
                averageColor.a = pow(averageColor.a, HARD_EDGE_POW_FACTOR);
                averageColor.rgb *= averageColor.a; // Premultiply
            }

            fragColor = averageColor;
        } else {
            fragColor = vec4(0.0); // Transparent if no alpha
        }
    }
}
